using UnityEngine;
using UnityEditor;
using UnityEngine.InputSystem;
using UnityEngine.InputSystem.LowLevel;
using System;
using System.IO;
using System.Text;
using System.Collections.Generic;
using ConRoi.Investigation.V36.R107;

namespace Unity.AI.Assistant.Agent.Dynamic.Extension.Editor
{
    internal class CommandScript : IRunCommand
    {
        public void Execute(ExecutionResult r)
        {
            var s = UnityEngine.Object.FindFirstObjectByType<InvestigationSession>();
            if (s.Page != "" || s.InspectionCount != 0 || File.Exists(s.SavePath) || !s.SavePath.StartsWith(@"C:\ConRoi_CheckoutTest\Test\PlaytestProfiles\Final_a789222_20261107_1740"))
                throw new Exception("Fresh launch profile required: " + s.SavePath);
            var w = EditorWindow.GetWindow(Type.GetType("UnityEditor.GameView,UnityEditor"));
            w.Focus();
            var b = new StringBuilder("Synthetic GameView click + InputSystem keys; state assertions via read-only API.\n");
            b.AppendLine("resolution=" + Screen.width + "x" + Screen.height + " profile=" + s.SavePath);
            var p = s.movement.transform.position;
            var settings = InputSystem.settings;
            string prior = JsonUtility.ToJson(settings);
            settings.editorInputBehaviorInPlayMode = InputSettings.EditorInputBehaviorInPlayMode.AllDeviceInputAlwaysGoesToGameView;
            settings.backgroundBehavior = InputSettings.BackgroundBehavior.IgnoreFocus;
            var kb = InputSystem.AddDevice<Keyboard>();
            kb.MakeCurrent();
            var q = new Queue<Action>();
            Action<bool, string> check = (v, m) =>
            {
                b.AppendLine((v ? "PASS " : "FAIL ") + m);
                if (!v)
                    throw new Exception(m);
            };
            Action<Key> key = k => InputSystem.QueueStateEvent(kb, new KeyboardState(k));
            Action release = () => InputSystem.QueueStateEvent(kb, new KeyboardState());
            q.Enqueue(() =>
            {
                check(Screen.width == 1920 && Screen.height == 1080, "1080p render dimensions");
                ScreenCapture.CaptureScreenshot("Test/Output/CleanCheckout/intro-1080.png");
            });
            q.Enqueue(() =>
            {
                check(s.Page == "" && s.data.introAccepted, "Start through intro button");
                key(Key.F5);
            });
            q.Enqueue(() =>
            {
                release();
                check(File.Exists(s.SavePath) && s.InspectionCount == 0 && !s.data.firstFloorRecorded && s.data.mapping.Count == 0 && !s.data.finalized, "F5 before first record, empty case saved only under private profile");
                key(Key.P);
            });
            q.Enqueue(() =>
            {
                release();
                check(s.Page == "dossier", "P opens empty dossier");
                ScreenCapture.CaptureScreenshot("Test/Output/CleanCheckout/empty-dossier-1080.png");
                key(Key.F6);
            });
            q.Enqueue(() =>
            {
                release();
                check(s.Page == "" && s.InspectionCount == 0 && !s.data.firstFloorRecorded && s.data.mapping.Count == 0 && !s.data.finalized, "F6 restores pre-record page and empty evidence");
                check(Vector3.Distance(p, s.movement.transform.position) < .05f, "load preserves saved spawn");
            });
            double next = EditorApplication.timeSinceStartup + 2;
            EditorApplication.CallbackFunction f = null;
            Action finish = () =>
            {
                EditorApplication.update -= f;
                InputSystem.RemoveDevice(kb);
                JsonUtility.FromJsonOverwrite(prior, settings);
                File.WriteAllText("Test/Output/CleanCheckout/before-record-calibrated.txt", b.ToString());
            };
            f = () =>
            {
                if (EditorApplication.timeSinceStartup < next)
                    return;
                next = EditorApplication.timeSinceStartup + 1.3;
                try
                {
                    if (q.Count == 0)
                    {
                        finish();
                        return;
                    }

                    q.Dequeue()();
                }
                catch (Exception e)
                {
                    b.AppendLine("FAIL " + e);
                    finish();
                }
            };
            EditorApplication.update += f;
            r.Log("Start bounded before-first-record save/load UI check");
        }
    }
}

